input.command:
python3 - <<EOF
import json
a=json.load(open('$TMPDIR/hoot.orig.json'));b=json.load(open('hoot.montagent.json'))
ta={t['name']:t for t in a['tracks']};tb={t['name']:t for t in b['tracks']}
for n in ta:
  print(n, 'same' if ta[n]==tb[n] else 'CHANGED')
for n in ('owl-forearm_left','owl-upper_arm_left'):
  for k in ('rotation','x','y'):
    ka=ta[n]['elements'][0].get(k); kb=tb[n]['elements'][0].get(k)
    if isinstance(ka,list):
      da={x['t']:x['v'] for x in ka}; db={x['t']:x['v'] for x in kb}
      bad=[t for t in da if 700<=t<=2700 and db.get(t+400)!=da[t] and abs(db.get(t+400,999)-da[t])>0.01]
      print(n,k,len(ka),len(kb),'mismatched shifted keys:',bad[:10])
EOF

